import { test } from "node:test";
import assert from "node:assert/strict";
import { calcTotal, type Item } from "../src/pricing.ts";
import { priceOf } from "../src/catalog.ts";

const round = (n: number) => Math.round(n * 100) / 100;

const subtotalOf = (items: Item[]) => items.reduce((sum, item) => sum + item.price * item.qty, 0);
const unitsOf = (items: Item[]) => items.reduce((sum, item) => sum + item.qty, 0);

test("no discount for a cart under 10 units", () => {
  const items: Item[] = [
    { sku: "apple", price: priceOf("apple"), qty: 5 },
    { sku: "pear", price: priceOf("pear"), qty: 4 },
  ];
  assert.equal(unitsOf(items), 9);
  assert.ok(subtotalOf(items) < 50, "cart must stay under $50");
  assert.equal(calcTotal(items), round(subtotalOf(items)));
});

test("10% off for a cart of exactly 10 units", () => {
  const items: Item[] = [
    { sku: "apple", price: priceOf("apple"), qty: 6 },
    { sku: "pear", price: priceOf("pear"), qty: 4 },
  ];
  assert.equal(unitsOf(items), 10);
  assert.ok(subtotalOf(items) < 50, "cart must stay under $50");
  assert.equal(calcTotal(items), round(subtotalOf(items) * 0.9));
});

test("10% off for a cart over 10 units", () => {
  const items: Item[] = [
    { sku: "apple", price: priceOf("apple"), qty: 8 },
    { sku: "pear", price: priceOf("pear"), qty: 5 },
  ];
  assert.equal(unitsOf(items), 13);
  assert.ok(subtotalOf(items) < 50, "cart must stay under $50");
  assert.equal(calcTotal(items), round(subtotalOf(items) * 0.9));
});

test("empty cart totals zero", () => {
  assert.equal(calcTotal([]), 0);
});

